content:
Save this as `index.html` and open it in a browser. It uses only the Three.js core ES module from cdnjs and includes custom drag-to-orbit and scroll-to-zoom controls.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Ball-and-Stick Water Molecule</title>

  <style>
    :root {
      color-scheme: dark;
      font-family:
        Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
        "Segoe UI", sans-serif;
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background:
        radial-gradient(circle at 50% 42%, #263746 0%, #111b25 55%, #080d13 100%);
    }

    #scene {
      position: fixed;
      inset: 0;
    }

    #scene::after {
      content: "";
      position: absolute;
      inset: 0;
      pointer-events: none;
      background:
        radial-gradient(
          ellipse at center,
          transparent 48%,
          rgba(0, 0, 0, 0.48) 100%
        );
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      outline: none;
      touch-action: none;
      cursor: grab;
    }

    canvas.dragging {
      cursor: grabbing;
    }

    .info {
      position: fixed;
      top: 24px;
      left: 28px;
      z-index: 2;
      pointer-events: none;
      color: #eef5fb;
    }

    .eyebrow {
      margin: 0 0 7px;
      color: #7fd7ff;
      font-size: 0.68rem;
      font-weight: 700;
      letter-spacing: 0.18em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.25rem, 3vw, 2rem);
      font-weight: 650;
      letter-spacing: -0.035em;
    }

    .formula {
      margin-top: 7px;
      color: #9fb0bf;
      font-size: 0.9rem;
      font-style: italic;
    }

    .angle-card {
      position: fixed;
      right: 24px;
      top: 24px;
      z-index: 2;
      padding: 12px 15px;
      border: 1px solid rgba(153, 196, 226, 0.16);
      border-radius: 12px;
      background: rgba(12, 20, 29, 0.58);
      box-shadow: 0 12px 36px rgba(0, 0, 0, 0.2);
      backdrop-filter: blur(12px);
      pointer-events: none;
    }

    .angle-card span {
      display: block;
      margin-bottom: 4px;
      color: #8fa2b3;
      font-size: 0.68rem;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    .angle-card strong {
      color: #ff7185;
      font-size: 1.25rem;
      font-variant-numeric: tabular-nums;
    }

    .hint {
      position: fixed;
      left: 50%;
      bottom: 20px;
      z-index: 2;
      transform: translateX(-50%);
      color: rgba(190, 207, 222, 0.6);
      font-size: 0.72rem;
      letter-spacing: 0.04em;
      pointer-events: none;
      white-space: nowrap;
    }

    @media (max-width: 600px) {
      .info {
        top: 18px;
        left: 18px;
      }

      .angle-card {
        top: auto;
        right: 16px;
        bottom: 48px;
      }

      .hint {
        bottom: 16px;
        font-size: 0.64rem;
      }
    }
  </style>
</head>

<body>
  <div id="scene"></div>

  <div class="info">
    <p class="eyebrow">Molecular Structure</p>
    <h1>Water</h1>
    <div class="formula">H₂O · bent molecule</div>
  </div>

  <div class="angle-card">
    <span>Bond angle</span>
    <strong>H—O—H 104°</strong>
  </div>

  <div class="hint">Drag to orbit · Scroll to zoom · Double-click to reset</div>

  <script type="module">
    import * as THREE from
      "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    const container = document.getElementById("scene");

    // Renderer
    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setClearColor(0x000000, 0);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.1;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;

    renderer.domElement.setAttribute(
      "aria-label",
      "Interactive three-dimensional ball-and-stick water molecule"
    );

    container.appendChild(renderer.domElement);

    // Scene and camera
    const scene = new THREE.Scene();

    const camera = new THREE.PerspectiveCamera(
      35,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );

    const target = new THREE.Vector3(0, 1.05, 0);

    const view = {
      theta: 0,
      phi: 1.38,
      radius: 5.15
    };

    const goal = {
      theta: view.theta,
      phi: view.phi,
      radius: view.radius
    };

    function updateCamera() {
      const sinPhi = Math.sin(view.phi);

      camera.position.set(
        target.x + view.radius * sinPhi * Math.sin(view.theta),
        target.y + view.radius * Math.cos(view.phi),
        target.z + view.radius * sinPhi * Math.cos(view.theta)
      );

      camera.lookAt(target);
    }

    updateCamera();

    // Lighting
    scene.add(new THREE.HemisphereLight(0xdceeff, 0x111820, 2.0));

    const keyLight = new THREE.DirectionalLight(0xffffff, 3.2);
    keyLight.position.set(4, 6, 5);
    keyLight.castShadow = true;
    keyLight.shadow.mapSize.set(1024, 1024);
    keyLight.shadow.bias = -0.0005;
    scene.add(keyLight);

    const fillLight = new THREE.PointLight(0x66aaff, 1.6, 12);
    fillLight.position.set(-4, 2, -3);
    scene.add(fillLight);

    const rimLight = new THREE.DirectionalLight(0xff6f88, 2.1);
    rimLight.position.set(0, 3, -5);
    scene.add(rimLight);

    // Materials
    const oxygenMaterial = new THREE.MeshStandardMaterial({
      color: 0xff4f70,
      roughness: 0.28,
      metalness: 0.04,
      emissive: 0x350711,
      emissiveIntensity: 0.22
    });

    const hydrogenMaterial = new THREE.MeshStandardMaterial({
      color: 0xf7f4ed,
      roughness: 0.24,
      metalness: 0.02,
      emissive: 0x242321,
      emissiveIntensity: 0.12
    });

    const bondMaterial = new THREE.MeshStandardMaterial({
      color: 0x687681,
      roughness: 0.52,
      metalness: 0.12
    });

    const sleeveMaterial = new THREE.MeshStandardMaterial({
      color: 0xaeb9c3,
      roughness: 0.4,
      metalness: 0.16
    });

    // Molecule geometry
    const molecule = new THREE.Group();
    molecule.rotation.y = -0.08;
    scene.add(molecule);

    const oxygenPosition = new THREE.Vector3(0, 1.35, 0);

    // The H-O-H angle is exactly 104 degrees.
    // Each hydrogen lies 52 degrees to either side of the vertical axis.
    const bondLength = 0.96;
    const halfBondAngle = THREE.MathUtils.degToRad(52);

    const hydrogenPositions = [
      new THREE.Vector3(
        Math.sin(halfBondAngle) * bondLength,
        -Math.cos(halfBondAngle) * bondLength,
        0
      ),
      new THREE.Vector3(
        -Math.sin(halfBondAngle) * bondLength,
        -Math.cos(halfBondAngle) * bondLength,
        0
      )
    ];

    const oxygen = new THREE.Mesh(
      new THREE.SphereGeometry(0.43, 48, 32),
      oxygenMaterial
    );

    oxygen.position.copy(oxygenPosition);
    oxygen.castShadow = true;
    oxygen.receiveShadow = true;
    molecule.add(oxygen);

    const hydrogenA = new THREE.Mesh(
      new THREE.SphereGeometry(0.29, 36, 24),
      hydrogenMaterial
    );

    const hydrogenB = new THREE.Mesh(
      new THREE.SphereGeometry(0.29, 36, 24),
      hydrogenMaterial
    );

    hydrogenA.position.copy(hydrogenPositions[0]);
    hydrogenB.position.copy(hydrogenPositions[1]);

    hydrogenA.castShadow = true;
    hydrogenB.castShadow = true;
    hydrogenA.receiveShadow = true;
    hydrogenB.receiveShadow = true;

    molecule.add(hydrogenA, hydrogenB);

    /**
     * Creates a cylinder aligned between two points.
     * The cylinder's local Y axis is rotated to match the direction.
     */
    function createBond(a, b, radius) {
      const direction = new THREE.Vector3().subVectors(b, a);
      const length = direction.length();

      const geometry = new THREE.CylinderGeometry(
        radius,
        radius,
        length,
        24,
        1,
        false
      );

      const bond = new THREE.Mesh(geometry, bondMaterial);
      bond.position.copy(a).add(b).multiplyScalar(0.5);
      bond.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction.normalize()
      );
      bond.castShadow = true;
      bond.receiveShadow = true;

      molecule.add(bond);
      return bond;
    }

    /**
     * Creates a short, wider cylinder and a shallow ring around each atom.
     * These act as the requested sleeves at the bond ends.
     */
    function createSleeve(center, axis, radius, length) {
      const direction = axis.clone().normalize();

      const sleeveGeometry = new THREE.CylinderGeometry(
        radius,
        radius,
        length,
        28,
        1,
        false
      );

      const sleeve = new THREE.Mesh(sleeveGeometry, sleeveMaterial);
      sleeve.position.copy(center);
      sleeve.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction
      );
      sleeve.castShadow = true;
      sleeve.receiveShadow = true;

      molecule.add(sleeve);

      // A shallow torus makes the sleeve edge visually distinct.
      const ringGeometry = new THREE.TorusGeometry(
        radius * 1.04,
        0.025,
        12,
        48
      );

      const ring = new THREE.Mesh(ringGeometry, sleeveMaterial);
      ring.position.copy(center);
      ring.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 0, 1),
        direction
      );
      ring.castShadow = true;

      molecule.add(ring);
    }

    // Main oxygen-hydrogen bonds.
    createBond(oxygenPosition, hydrogenPositions[0], 0.105);
    createBond(oxygenPosition, hydrogenPositions[1], 0.105);

    // Shallow sleeves centered on each atom, aligned along the nearby bond.
    createSleeve(oxygenPosition, new THREE.Vector3(1, -1, 0), 0.145, 0.22);
    createSleeve(hydrogenPositions[0], new THREE.Vector3(1, 1, 0), 0.145, 0.22);
    createSleeve(hydrogenPositions[1], new THREE.Vector3(1, 1, 0), 0.145, 0.22);

    // Custom camera controls — no external controls addon.
    let dragging = false;
    let lastX = 0;
    let lastY = 0;

    const canvas = renderer.domElement;

    canvas.addEventListener("pointerdown", (event) => {
      dragging = true;
      lastX = event.clientX;
      lastY = event.clientY;
      canvas.setPointerCapture(event.pointerId);
      canvas.classList.add("dragging");
    });

    canvas.addEventListener("pointermove", (event) => {
      if (!dragging) return;

      const deltaX = event.clientX - lastX;
      const deltaY = event.clientY - lastY;

      lastX = event.clientX;
      lastY = event.clientY;

      goal.theta -= deltaX * 0.006;
      goal.phi = THREE.MathUtils.clamp(
        goal.phi - deltaY * 0.006,
        0.25,
        2.75
      );
    });

    function endDrag(event) {
      dragging = false;
      canvas.classList.remove("dragging");

      if (event.pointerId !== undefined && canvas.hasPointerCapture(event.pointerId)) {
        canvas.releasePointerCapture(event.pointerId);
      }
    }

    canvas.addEventListener("pointerup", endDrag);
    canvas.addEventListener("pointercancel", endDrag);

    canvas.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        goal.radius = THREE.MathUtils.clamp(
          goal.radius * Math.exp(event.deltaY * 0.001),
          3.4,
          9
        );
      },
      { passive: false }
    );

    function resetView() {
      goal.theta = 0;
      goal.phi = 1.38;
      goal.radius = 5.15;
    }

    canvas.addEventListener("dblclick", resetView);
    canvas.addEventListener("contextmenu", (event) => event.preventDefault());

    function resize() {
      const width = container.clientWidth;
      const height = container.clientHeight;

      camera.aspect = width / height;
      camera.updateProjectionMatrix();

      renderer.setSize(width, height, false);
    }

    window.addEventListener("resize", resize);
    resize();

    // Smooth camera movement
    renderer.setAnimationLoop(() => {
      view.theta += (goal.theta - view.theta) * 0.12;
      view.phi += (goal.phi - view.phi) * 0.12;
      view.radius += (goal.radius - view.radius) * 0.12;

      updateCamera();
      renderer.render(scene, camera);
    });
  </script>
</body>
</html>
```
